import{_ as a,c as i,o,a2 as r}from"./chunks/framework.bjzS3PU6.js";const d=JSON.parse('{"title":"SnarkCast","description":"","frontmatter":{},"headers":[],"relativePath":"entries/organizations/SnarkCast.md","filePath":"entries/organizations/SnarkCast.md"}'),t={name:"entries/organizations/SnarkCast.md"};function n(s,e,l,c,p,h){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="snarkcast" tabindex="-1">SnarkCast <a class="header-anchor" href="#snarkcast" aria-label="Permalink to &quot;SnarkCast&quot;">​</a></h1><hr><p><strong>TYPE</strong>: Satirical Podcast<br><strong>HOST</strong>: <a href="./../people/Milton-Plumb">Milton Plumb</a><br><strong>GENRE</strong>: Cryptocurrency commentary, conspiracy theories<br><strong>STATUS</strong>: Active (as of November 2025)</p><hr><p><strong>SnarkCast</strong> is a satirical podcast covering cryptocurrency markets, government conspiracy theories, and alleged corporate-government collusion. Hosted by <a href="./../people/Milton-Plumb">Milton Plumb</a>, the program features guest appearances by financial commissioners, conspiracy theorists, and market analysts discussing fringe theories and speculative investments.</p><p><strong>At a glance</strong></p><ul><li>Satirical podcast covering cryptocurrency and conspiracy theories</li><li>Hosted by <a href="./../people/Milton-Plumb">Milton Plumb</a> with recurring guest commentators</li><li>Features theatrical presentation style with exaggerated reactions and sound effects</li><li>Covers theories about <a href="./Miter-Corporation">Miter Corporation</a> and government research programs</li><li>Warned of <a href="./The-Bloc">The Bloc</a>&#39;s blockchain activities involving <a href="./../subjects/G-BOY">G*BOY</a></li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><em>SnarkCast</em> operates as a satirical podcast that blends cryptocurrency market commentary with conspiracy theory discussion. The program&#39;s format features host <a href="./../people/Milton-Plumb">Milton Plumb</a> moderating conversations with guest experts, including financial commissioners and conspiracy theorists, who provide theatrical commentary on government operations and speculative investments.</p><p>The show&#39;s aesthetic reportedly includes vintage audio equipment and retro production design, creating an atmosphere consistent with 1990s and early 2000s alternative media culture. Visual elements allegedly include symbolic props such as government-associated eagles and collectible toys.</p><h2 id="format-and-style" tabindex="-1">Format and Style <a class="header-anchor" href="#format-and-style" aria-label="Permalink to &quot;Format and Style&quot;">​</a></h2><h3 id="presentation-approach" tabindex="-1">Presentation Approach <a class="header-anchor" href="#presentation-approach" aria-label="Permalink to &quot;Presentation Approach&quot;">​</a></h3><p><em>SnarkCast</em> employs a satirical format that simultaneously mocks and engages with conspiracy theories and financial speculation. Host Plumb&#39;s measured, deadpan delivery provides counterbalance to theatrical guest performances, creating dynamic tension between conventional skepticism and conspiratorial elaboration.</p><p>Episodes feature:</p><ul><li>Host-guest dialogue with dramatic interruptions and reactions</li><li>Technical producer managing visual displays of documents and footage</li><li>Sound effects including screaming, animal noises, and musical elements</li><li>Episodic structure with dramatic teasers for upcoming episodes</li><li>Integration of visual elements (files, footage, props) into audio format</li></ul><h3 id="episode-structure" tabindex="-1">Episode Structure <a class="header-anchor" href="#episode-structure" aria-label="Permalink to &quot;Episode Structure&quot;">​</a></h3><p>Episodes typically open with Plumb presenting conventional interpretations of events, which guests then challenge or expand into conspiracy theories. This structure allows Plumb to function as audience surrogate, expressing familiarity with theories while maintaining initial skepticism.</p><p>Episode conclusions feature dramatic announcements and teasers with rhetorical questions, such as &quot;Next week on SnarkCast, will you choose rich or will rich choose you?&quot;</p><h2 id="notable-episodes" tabindex="-1">Notable Episodes <a class="header-anchor" href="#notable-episodes" aria-label="Permalink to &quot;Notable Episodes&quot;">​</a></h2><h3 id="conspirazorg-on-miter-corporation-november-12-2025" tabindex="-1">Conspirazorg on Miter Corporation (November 12, 2025) <a class="header-anchor" href="#conspirazorg-on-miter-corporation-november-12-2025" aria-label="Permalink to &quot;Conspirazorg on Miter Corporation (November 12, 2025)&quot;">​</a></h3><p><em>SnarkCast</em> featured conspiracy theorist <a href="./../people/Conspirazorg">Conspirazorg</a> discussing alleged operations at <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a>. The episode explored theories about <a href="./Miter-Corporation">Miter Corporation</a> conducting experiments on children to develop psychic weapons.</p><p>Key claims discussed:</p><ul><li>Kidnapping of &quot;homeless babies&quot; as experimental subjects</li><li>Traumatic experiments involving gravity manipulation and sensory deprivation</li><li>Distribution of &quot;animal badges&quot; to subjects for psychological manipulation</li><li>Development of psychic capabilities for military applications</li><li>Escape of subject identified as <a href="./../subjects/G-BOY">G*BOY</a> who became online symbol</li></ul><p>Conspirazorg directed the show&#39;s technical producer to display files and footage supporting his theories, including documentation about St. Juniper Secure Lab and footage of &quot;the Fox kid&quot; being chased through <a href="./../locations/Saint-Juniper">Saint Juniper</a>.</p><h3 id="rectford-shillman-on-cryptocurrency-risks-november-26-2025" tabindex="-1">Rectford Shillman on Cryptocurrency Risks (November 26, 2025) <a class="header-anchor" href="#rectford-shillman-on-cryptocurrency-risks-november-26-2025" aria-label="Permalink to &quot;Rectford Shillman on Cryptocurrency Risks (November 26, 2025)&quot;">​</a></h3><p><em>SnarkCast</em> hosted Commissioner <a href="./../people/Rectford-Shillman">Rectford Shillman</a> for discussion of cryptocurrency investment risks, particularly focusing on government-unapproved projects. The episode addressed concerns about &quot;the salami blockchain&quot; project&#39;s connection to G*BOY.</p><p>Key topics:</p><ul><li>Warnings against investing in memecoins or NFTs unsanctioned by government or approved influencers</li><li>Initial approval for blockchain projects with mainstream legitimacy (stock exchange participation)</li><li>Alarm upon discovering connection to G*BOY</li><li>Characterization of G*BOY as &quot;terrorist&quot;</li><li>Primary concern identified as <a href="./The-Bloc">The Bloc</a>, described as &quot;hacktivists&quot; and &quot;terrorists&quot;</li><li>Warning that The Bloc was planning &quot;something with G*BOY on The blockchain very soon&quot;</li></ul><p>This episode occurred approximately two weeks before The Bloc launched the $GBOY memecoin, which was subsequently covered by competing program <a href="./Market-Talk">Market Talk</a>.</p><h2 id="recurring-guests" tabindex="-1">Recurring Guests <a class="header-anchor" href="#recurring-guests" aria-label="Permalink to &quot;Recurring Guests&quot;">​</a></h2><ul><li><a href="./../people/Conspirazorg">Conspirazorg</a> — Conspiracy theorist specializing in government operations and corporate misconduct</li><li><a href="./../people/Rectford-Shillman">Rectford Shillman</a> — Financial commissioner providing cryptocurrency market commentary</li></ul><h2 id="thematic-content" tabindex="-1">Thematic Content <a class="header-anchor" href="#thematic-content" aria-label="Permalink to &quot;Thematic Content&quot;">​</a></h2><p><em>SnarkCast</em> coverage typically addresses:</p><ul><li>Cryptocurrency market speculation and regulation</li><li>Government oversight of blockchain projects</li><li>Conspiracy theories about covert research programs</li><li>Corporate-government collusion allegations</li><li>Hacktivist and activist organization activities</li><li>Mainstream versus unsanctioned financial projects</li><li>Institutional coverups and misdirection narratives</li></ul><p>The program&#39;s satirical approach creates ambiguity about whether its concerns are genuine warnings, exaggerated mockery of conspiracy culture, or performance art engaging with both modes simultaneously.</p><h2 id="relationship-to-other-media" tabindex="-1">Relationship to Other Media <a class="header-anchor" href="#relationship-to-other-media" aria-label="Permalink to &quot;Relationship to Other Media&quot;">​</a></h2><p><em>SnarkCast</em> exists within a media ecosystem that includes financial analysis programs like <a href="./Market-Talk">Market Talk</a>. While <em>Market Talk</em> focuses on conventional financial analysis with professional anchor presentation, <em>SnarkCast</em> emphasizes conspiracy theories and theatrical commentary.</p><p>Both programs have covered <a href="./The-Bloc">The Bloc</a>&#39;s cryptocurrency activities involving <a href="./../subjects/G-BOY">G*BOY</a>, with <em>SnarkCast</em> providing advance warnings in late November 2025 and <em>Market Talk</em> analyzing the actual token launch in December 2025.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../people/Milton-Plumb">Milton Plumb</a></li><li><a href="./../people/Conspirazorg">Conspirazorg</a></li><li><a href="./../people/Rectford-Shillman">Rectford Shillman</a></li><li><a href="./Market-Talk">Market Talk</a></li><li><a href="./../subjects/G-BOY">G*BOY</a></li><li><a href="./The-Bloc">The Bloc</a></li><li><a href="./Miter-Corporation">Miter Corporation</a></li><li><a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a></li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li><strong>SnarkCast episode</strong> — Featuring Conspirazorg (November 12, 2025) <ul><li>Satirical podcast discussing Miter Corporation conspiracy theories and G*BOY</li></ul></li><li><strong>SnarkCast episode</strong> — Featuring Rectford Shillman (November 26, 2025) <ul><li>Satirical podcast discussing cryptocurrency risks and The Bloc&#39;s blockchain activities</li></ul></li></ol><hr><p><em>This article is part of the Saint Juniper Research Documentation Project</em></p>',44)])])}const m=a(t,[["render",n]]);export{d as __pageData,m as default};
